//! KAT court for the kernel digest seam.
//!
//! Vectors: BLAKE3 official test vectors (empty, "abc", the 2500-byte
//! multi-chunk input `bytes(i % 251) for i in 0..2500`) — the same vectors
//! Y2's `packages/worker/src/ocel/chain.test.ts` used (b3sum 1.8.5
//! reference, BLAKE3-team/BLAKE3 reference CLI). Keyed vectors use a demo
//! key (`"whats the Elephant-in-the-Room?"` — 31 bytes, space-padded to the
//! 32-byte key), digests generated by `b3sum --keyed` (b3sum 1.8.5).
//!
//! Both seam implementations run the vectors: upstream on full scope,
//! vendored on its declared single-chunk scope. This is the proof the
//! vendored copy's UNVERIFIED-pending-KAT row was waiting for.

use repop_kernel::digest::{Digest256, KeyedDigestError, UpstreamBlake3, VendoredKeyedBlake3};

/// BLAKE3 spec demo key, space-padded to 32 bytes (see module docs).
const KAT_KEY: [u8; 32] = *b"whats the Elephant-in-the-Room? ";

/// `bytes(i % 251) for i in 0..n`.
fn pattern(n: usize) -> Vec<u8> {
    (0..n).map(|i| (i % 251) as u8).collect()
}

const EMPTY_HEX: &str =
    "af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262";

const ABC_HEX: &str =
    "6437b3ac38465133ffb63b75273a8db548c558465d79db03fd359c6cd5bd9d85";

/// 2500-byte multi-chunk vector: `bytes(i % 251) for i in 0..2500`.
const P2500_HEX: &str =
    "95e809954ebdd862debeb347d5715c09e73d150cd0704d4bbd834993a730e2ff";

/// Keyed vectors (b3sum --keyed, b3sum 1.8.5, padded demo key): (len, hex).
/// len 3 is the literal input "abc"; other lengths use the pattern input.
const KATS_KEYED: &[(usize, &str)] = &[
    (
        0,
        "715a96e6ec2cba753bec3d67f05fcb3e796519eb5dbd858030c65f88a16d1913",
    ),
    (
        3,
        "b8c8423b44fbc1de11179f63a49e4ce94e99e5ae6ff90f0e043ba5e483c744ce",
    ),
    (
        1000,
        "b464f1b57c801d31b3c1137881b0b4f4ebc0b830195f658580e32dbb208bb5e2",
    ),
    (
        2500,
        "ad0956563f760eff9e9e7f7e6b48d82ff06b4940f70222f6af9e5beffea35e74",
    ),
];

fn hex(d: &[u8; 32]) -> String {
    d.iter().map(|b| format!("{b:02x}")).collect()
}

#[test]
fn upstream_blake3_kat_unkeyed() {
    assert_eq!(hex(&UpstreamBlake3.digest(b"")), EMPTY_HEX);
    assert_eq!(hex(&UpstreamBlake3.digest(b"abc")), ABC_HEX);
    let data = pattern(2500);
    assert_eq!(hex(&UpstreamBlake3.digest(&data)), P2500_HEX);
}

#[test]
fn vendored_blake3_kat_unkeyed_single_chunk() {
    // In-scope vector: empty input (single chunk). The 2500-byte multi-chunk
    // vector is out of the vendored copy's declared scope (single-chunk
    // refusal, never truncation) — scope boundary recorded in the D7 ledger.
    assert_eq!(hex(&VendoredKeyedBlake3.digest(b"")), EMPTY_HEX);
    assert_eq!(hex(&VendoredKeyedBlake3.digest(b"abc")), ABC_HEX);
}

#[test]
fn upstream_blake3_kat_keyed() {
    for (n, expected) in KATS_KEYED {
        let data = if *n == 3 {
            b"abc".to_vec()
        } else {
            pattern(*n)
        };
        let got = UpstreamBlake3.digest_keyed(&KAT_KEY, &data).unwrap();
        assert_eq!(hex(&got), *expected, "upstream keyed n={n}");
    }
}

#[test]
fn vendored_blake3_kat_keyed_witnessed_drift() {
    // DRIFT WITNESS (resolution evidence for the D7 UNVERIFIED rows): the
    // vendored copy passes empty/abc but FAILS the 1000-byte keyed vector —
    // its multi-block path is spec-nonconformant. Pinned as assert_ne!: if
    // someone fixes the vendor module, this test goes RED and forces the
    // row to be re-triaged against upstream equality before flipping.
    for (n, expected) in KATS_KEYED {
        if *n <= 64 {
            let data = if *n == 3 {
                b"abc".to_vec()
            }
            else {
                pattern(*n)
            };
            assert_eq!(
                hex(&VendoredKeyedBlake3.digest_keyed(&KAT_KEY, &data).unwrap()),
                *expected,
                "vendored keyed n={n} (single block: must match)"
            );
        } else if *n == 1000 {
            let data = pattern(1000);
            let got = hex(&VendoredKeyedBlake3.digest_keyed(&KAT_KEY, &data).unwrap());
            assert_ne!(
                got, *expected,
                "vendor copy now matches upstream at n=1000 — re-triage the D7 drift row"
            );
            assert_eq!(got, "11694e91afb72b33091847397e4a942f45dc965561dfe12dcbc06cc14760d129");
        }
    }
}

#[test]
fn vendored_refuses_multi_chunk_keyed() {
    let data = pattern(2500);
    assert_eq!(
        VendoredKeyedBlake3.digest_keyed(&KAT_KEY, &data),
        Err(KeyedDigestError::InputTooLong { observed: 2500 })
    );
}

#[test]
fn vendored_refuses_multi_chunk_unkeyed() {
    // The seam guards before calling the vendor module, so oversized input
    // is refused (panic at the seam assertion), never silently truncated.
    let result = std::panic::catch_unwind(|| {
        let _ = VendoredKeyedBlake3.digest(&pattern(2500));
    });
    assert!(
        result.is_err(),
        "vendored unkeyed must not accept 2500 bytes"
    );
}

#[test]
fn default_seam_is_upstream() {
    // The kernel's default path (receipt/state call sites) produces
    // upstream digests: correct on the multi-chunk vector.
    let got = repop_kernel::digest::digest(&pattern(2500));
    assert_eq!(hex(&got), P2500_HEX);
}
